app_alert.code:
text = device.alert()
if text:
    print("dialog up:", text)

app_logs.code:
logs = device.device_logs(app="com.example.shop", level="error")
for entry in logs["entries"]:
    print(entry["time"], entry["tag"], entry["message"])

app_map.code:
diff = device.map_diff()
for e in diff["added"]:
    print("+", e.ref, e.label)
for c in diff["changed"]:
    print("~", c["after"].ref, c["after"].label, c["what"])

Device.code:
with mobium.start(platform="android", app="com.android.settings") as device:
    for el in device.map():
        print(el.ref, el.label)

DeviceInfo.code:
for info in device.devices():
    kind = "emulator" if info.emulator else "device"
    print(info.id, info.model, kind)

MobiumError.code:
try:
    device.tap("text=Continue")
except mobium.MobiumError as e:
    print(e.code, e.message)
    print(e.remedy)

NoSuchElementError.code:
from mobium import NoSuchElementError

try:
    device.tap("text=Continue")
except NoSuchElementError:
    device.scroll_to("text=Continue")

TimedOutError.code:
try:
    device.wait_for("text=Welcome back", timeout_ms=5000)
except mobium.TimedOutError as e:
    print("still not there:", e.message)

UnsupportedError.code:
try:
    device.press("back")
except mobium.UnsupportedError:
    device.tap("label=Back")  # iOS has no back button

NoDeviceError.code:
try:
    device = mobium.start()
except mobium.NoDeviceError as e:
    print(e.remedy)

DeviceNotReadyError.code:
try:
    device.launch("com.android.settings")
except mobium.DeviceNotReadyError:
    device.set_screen_locked(False)
    device.launch("com.android.settings")

NotConfirmedError.code:
try:
    device.timezone("Asia/Tokyo")
except mobium.NotConfirmedError as e:
    print("not applied:", e.message)

ElementNotReachableError.code:
try:
    device.tap("text=Buy")
except mobium.ElementNotReachableError as e:
    print(e.details)

InvalidArgumentError.code:
try:
    device.set_orientation("left")
except mobium.InvalidArgumentError as e:
    print(e.message)

ToolchainMissingError.code:
try:
    device = mobium.start(platform="ios")
except mobium.ToolchainMissingError as e:
    print(e.remedy)

DeviceServerError.code:
try:
    device.tap("@e2")
except mobium.DeviceServerError as e:
    print(e.details.get("w3c"))

InternalError.code:
try:
    device.map()
except mobium.InternalError as e:
    if e.retryable:
        device.map()
